"""Cybersecurity playbook: overview guides that answer the BIG questions offline, in English, French, Kinyarwanda and Kiswahili:
how attackers (hackers and cybercriminals) work, the families of attacks, how security engineers protect systems, the MITRE ATT&CK tactics,
how accounts and phones get hacked and how to prevent it, how to avoid scams and what to do if you were scammed, careers and certifications.
Protective, awareness-level content only: it names techniques so people and defenders can recognise and stop them; it gives no instructions for
committing an attack. Facts are standard textbook/framework material (NIST CSF, MITRE ATT&CK, OWASP, ISO/IEC 27001). No phone numbers are stored.
fr/rw/sw wording is a DRAFT for review by fluent speakers. Pure Python; find(question, lang) -> guide entry or None."""
from __future__ import annotations
from textutil import fold, has_phrase, entry, LANGS

_RAW = []
NOTE = {"en": "Awareness-level overview for protection. Check official guidance (for example NCSA Rwanda) for your situation.",
        "fr": "Aperçu de sensibilisation pour se protéger. Consultez les consignes officielles (par exemple NCSA Rwanda) selon votre situation.",
        "rw": "Incamake yo gukangurira kwirinda. Reba amabwiriza yemewe (urugero NCSA Rwanda) hakurikijwe uko ubyifashe.",
        "sw": "Muhtasari wa uhamasishaji kwa ulinzi. Angalia mwongozo rasmi (mfano NCSA Rwanda) kulingana na hali yako."}


def _add(id_, kw, title, answer, steps, label, related=None):
    st = {l: list(steps[i]) for i, l in enumerate(LANGS)}
    ans = {l: answer[i] + "\n\n_" + NOTE[l] + "_" for i, l in enumerate(LANGS)}
    e = entry(id_, "cyber_playbook", dict(zip(LANGS, title)), ans, st, dict(zip(LANGS, label)), related)
    _RAW.append((e, [fold(x) for x in kw.split("|") if x.strip()]))


